INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "お！\nあそこに困ってそうな人発見！", "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 1, 0, 0, 1, 1001, 1.4, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 0, 1, "春咲 ひより");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "大切な人を\n守れるようになりたい…って", "みんなみたいに\nわたしも強くならなきゃ", 1, 0, 0, 1, 1002, 1.4, "わ、わたし、\nなに言ってるんだろ\nあはは…", 0, 1, "草野 優衣");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "キミに必要な集中力と感性が", "フェンシングを始めてみては？", 1, 0, 0, 1, 1003, 1.4, "少しは磨かれると思いますよ。", 0, 1, "士条 怜");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "今日はなにして遊ぶ？", "ねぇ、にいちゃん！", 1, 0, 0, 1, 1004, 1.5, "みそぎはねぇ、\nかくれんぼやりたい！", 0, 1, "穂高 みそぎ");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "ねぇ…", "風宮あかりです", 1, 0, 0, 1, 1006, 1.4, "私といっしょに…\nいかない？", 0, 1, "風宮 あかり");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "プリンたべたいのー", "出雲宮子なのー", 1, 0, 0, 1, 1007, 1.5, "食べ物の恨みは怖いのー", 0, 1, "出雲 宮子");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "キミもボクの美貌に\n吸い寄せられたんだね。", "ボクは虹村雪。", 1, 0, 0, 1, 1008, 1.4, "いいよ。\n見られることは運命さ…", 0, 1, "虹村 雪");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", "フッ…聞いて後悔するがいい！", 1, 0, 0, 1, 1009, 1.4, "人呼んで「疾風の冥姫」!!", 0, 1, "柊杏奈");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", "マホマホ王国のプリンセス、\nまほ姫どす", 1, 0, 0, 1, 1010, 1.5, "ほんまおおきにやわ～♪", 0, 1, "姫宮 真歩");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "生き別れたお兄ちゃんを探して\n三千世界！", "衣之咲璃乃です！", 1, 0, 0, 1, 1011, 1.4, "ここで会ったが\n100年目～！", 0, 1, "衣之咲 璃乃");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "ち、超能力って…\n何のことかな～？", "私はハツネ、\n結構強いんだよ。\nきらーん☆", 1, 0, 0, 1, 1012, 1.4, "…って、お願い！\n誰にも言わないでおいて～！", 0, 1, "柏崎 初音");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "一応カリスマ読モJKやってまっす！", "ちょす！\n美波鈴奈だよ～♪", 1, 0, 0, 1, 1016, 1.4, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 0, 1, "美波 鈴奈");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "東京は遊園地みたいなところさー", "はいたーい。\n喜屋武香織さー。", 1, 0, 0, 1, 1017, 1.4, "でも、沖縄もとってもいいとこさー", 0, 1, "喜屋武 香織");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "先生って呼ばれるのは\nくすぐったいから", "支倉伊緒です。", 1, 0, 0, 1, 1018, 1.4, "イオちゃんって呼んでね。", 0, 1, "支倉 伊緒");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "あ！/\お兄ちゃ～ん\nまってよ～", "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 1, 0, 0, 1, 1020, 1.5, "ミミをおいてかないでぇ～", 0, 1, "茜 ミミ");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "あの……\nふぇ……", "あ…あの…えっと…\n栗…林…くるみ…です……", 1, 0, 0, 1, 1021, 1.5, "ふぇぇぇぇぇん……", 0, 1, "栗林 くるみ");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "こんな私に貴重な時間を\n割いていただき、", "風宮よりです。\nあああああ！", 1, 0, 0, 1, 1022, 1.4, "なんてありがとうございます！", 0, 1, "風宮 より");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "おにいちゃんどこいくの？\nえ？", "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 1, 0, 0, 1, 1023, 1.5, "私こっち行きたいー\nね、早く早くー", 0, 1, "北条 綾音");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "ふ、不束者ですが\nどうぞ末永く…って、", "わっ…わっ…私、\n天野すずめといいます！", 1, 0, 0, 1, 1025, 1.4, "これて何か違う…\nあああすみません！", 0, 1, "天野 すずめ");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "あなたは…運命の……\n伴侶……", "……クスクス…私は\n…倉石恵理子……", 1, 0, 0, 1, 1027, 1.4, "離しませんわ………\n絶対に…!!", 0, 1, "倉石 恵理子");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 1, 0, 0, 1, 1028, 1.4, "…そうでしょ？？", 0, 1, "佐々木 咲恋");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "ぇっと…\nキミ、私のこと知らないの?!", "桜井望だよ！\nよろしくねっ", 1, 0, 0, 1, 1029, 1.4, "あはは、\n私もまだまだだなぁ～", 0, 1, "桜井 望");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "初めまして、\n私はニノン・ジュベール申すデス！", "デケデケデンっ！", 1, 0, 0, 1, 1030, 1.4, "ショーグン、\nワタシと一緒に天下統一デース！", 0, 1, "ニノン・ジュベール");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "でもって私の隣にいるのが……\nえ、見えない？", "上喜しのぶです。\n手元のドクロが父です。", 1, 0, 0, 1, 1031, 1.4, "おかしいですね……", 0, 1, "上喜 しのぶ");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "けんども\nそれには足りないモンが…", "目指すはビッグな\nお笑い芸人だっぺ！", 1, 0, 0, 1, 1033, 1.5, "そう、\nオラのボケに突っ込める相方が…！", 0, 1, "野戸まひる");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "ちょっと緊張しちゃって…", "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 1, 0, 0, 1, 1034, 1.4, "ちょ\nちょっと一杯飲んできます…！", 0, 1, "綾瀬 ゆかり");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "知らない人とは話しちゃいけないので", "氷川鏡華…です", 1, 0, 0, 1, 1036, 1.5, "これ以上お話しすることは…\nないです！", 0, 1, "氷川 鏡華");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "……あ、アラーム。", "柏崎…栞です。", 1, 0, 0, 1, 1038, 1.4, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 0, 1, "柏崎 栞");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "私、一人も友達がいなくて……", "ふ、双葉碧です。", 1, 0, 0, 1, 1040, 1.4, "野に咲く花が、\n唯一の話相手です。", 0, 1, "双葉 碧");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", "三角千歌です。", 1, 0, 0, 1, 1042, 1.4, "そう思っています。", 0, 1, "三角 千歌");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "あぁ？\nお前のそいつの仲間か？", "安芸真琴だ。", 1, 0, 0, 1, 1043, 1.4, "う、疑ってすまなかったな…", 0, 1, "安芸 真琴");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "生けとし生ける全ての者よ！", "わらわこそは夜を総べる者！", 1, 0, 0, 1, 1044, 1.4, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 0, 1, "イリヤ・オーンスタイン");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "ぐふふふふ……はっ！", "そこで騎士は妖精を乱暴に……", 1, 0, 0, 1, 1045, 1.4, "ｌク、クウカに何かご用ですか!?", 0, 1, "遠見 空花");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "自由気ままで♪\n寝て遊んで、食べてケンカして…", "宮坂たまきにゃ♪\n猫はいいにゃよ？", 1, 0, 0, 1, 1046, 1.4, "う～ん…\n猫ってホントに最高にゃ～♪", 0, 1, "宮坂たまき");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "それでは早速クエストに…", "大神美冬よ！", 1, 0, 0, 1, 1048, 1.4, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 0, 1, "大神 美冬");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "クエストもバトルも\n掃除も洗濯も", "星野静流だよ！", 1, 0, 0, 1, 1049, 1.4, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 0, 1, "星野静流");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "見ての通りの\nセクシー美少女で", "アタシは玉泉美咲。", 1, 0, 0, 1, 1050, 1.5, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 0, 1, "玉泉美咲");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "？？？？", "？？？", 1, 0, 0, 1, 1052, 1.4, "？？？？", 0, 1, "リマ");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", 1, 0, 0, 1, 1053, 1.5, "そ、そこまでいうなら\nもらってやる", 0, 1, "モニカ・ヴァイスヴィント");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", 1, 0, 0, 1, 1058, 1.5, "そ、そこまでいうなら\nもらってやる", 0, 1, "ペコリーヌ");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", 1, 0, 0, 1, 1059, 1.5, "そ、そこまでいうなら\nもらってやる", 0, 1, "コッコロ");
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, 0, 2, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", 1, 0, 0, 1, 1060, 1.5, "そ、そこまでいうなら\nもらってやる", 0, 1, "キャル");
